			/*
			 * 사용자 정의 컨트롤에서 insert 이벤트 발생 시 호출.
			 * 신규 클릭 이벤트
			 * 프로그램목록
			 */
			function onComBtnGrid20Insert(e){
			    e.preventDefault();
			    
			    if (app.lookup("dsDetailInfo").getValue(0, "APRV_STTS_SE_CD") != "2"){
			    	util.Msg.alert(app,"자원변경요청이 승인되지 않았습니다.\n자원 승인을 먼저 진행해 주세요.");
			    	return;
			    }

			    var orgResrceNo = app.lookup("dsDetailInfo").getValue(0, "ORG_RESRCE_NO");
			    var resrceNo    = util.DataSet.getValue(app, "dsDetailInfo", 0, "RESRCE_NO");
			    
			    var voInitValue = {
			        "RESRCE_NO" : resrceNo,
			        "MULTI_CHC" : true
			    };
			    var voDataSet   = app.lookup("dsProgramList");

			    //프로그램조회
			    util.Dialog.open(app, "app/itgcm/bizcmmns/popup/progrmInqPop", "프로그램조회", 1152, 648, function(e){

			        //콜백함수        
			        var dialog      = e.control;
			        /** @type Array */
			        var voReturnVals = dialog.returnValue;

			        if(!ValueUtil.isNull(voReturnVals)){
			            for(var idx = 0; idx < voReturnVals.length; idx++){
			                var voReturnVal = voReturnVals[idx];
			                if(resrceNo != voReturnVal["RESRCE_NO"]) {
			                    util.Msg.alert(app, "선택한 프로그램의 자원이 자원제공서비스과 동일하지 않습니다.");
			                    return;
			                }

			                for(var i=0; i<voDataSet.getRowCount(); i++) {
			                    var sProgrmNo = voDataSet.getValue(i, "PROGRM_NO");

			                    if(sProgrmNo == voReturnVal["PROGRM_NO"]) {
			                        util.Msg.alert(app, "동일한 프로그램이 존재합니다.\n다시 선택해주십시요.");
			                        return;
			                    }
			                }
			            }
			            
			            voReturnVals = voReturnVals.reverse();
			            for(var idx = 0; idx < voReturnVals.length; idx++){
			                var voReturnVal = voReturnVals[idx];
			                app.lookup("grdSrvcGrPlanProgMainList").insertRowData(0, false, voReturnVal);
			                
			                if(orgResrceNo != resrceNo) {
			                    app.lookup("dsProgramList").setValue(0, "SRVC_PVSN_PLAN_NO", "");        //서비스제공계획번호
			                } else {
			                    app.lookup("dsProgramList").setValue(0, "SRVC_PVSN_PLAN_NO", sPvPlanNo); //서비스제공계획번호
			                }
			            }
			            setDsProgramRowCnt();
			            util.Control.redraw(app, "grpSrvcGrPlanProgMainList");
			        }

			    }, voInitValue);
			}

